script.setup:
const gl = ctx.gl;
const image = await ctx.utils.loadTexture('poster-test.png', {flipY:true, wrap:'clamp', filter:'linear', mipmap:true});
ctx.state.texture = image.texture;
ctx.state.aspect = image.width / image.height;
const deformation = `
vec3 cloth(vec2 uv) {
  float t = u_time * u_speed;
  float freeEdge = 0.18 + 0.82 * pow(1.0-uv.y, 0.8);
  float x = (uv.x-0.5) * 4.8;
  float y = (uv.y-0.5) * u_height;
  float broad = sin(uv.x*7.3 - t*1.1 + uv.y*2.8);
  float ripple = sin(uv.x*15.5 + uv.y*5.0 - t*1.65);
  float cross = sin(uv.y*8.0 - uv.x*3.8 + t*0.65);
  float z = u_flutter * freeEdge * (0.36*broad + 0.115*ripple + 0.07*cross);
  z += 0.08 * sin(uv.x*3.14159265) * sin(uv.y*3.14159265);
  y -= 0.065 * sin(uv.x*3.14159265) * (0.5+0.5*uv.y);
  y += u_flutter * freeEdge * 0.028 * sin(uv.x*9.0-t*1.1);
  x += u_flutter * freeEdge * 0.018 * sin(uv.y*6.0+t*0.7);
  return vec3(x,y,z);
}`;
const vs = `#version 300 es
precision highp float;
layout(location=0) in vec3 a_position;
layout(location=2) in vec2 a_uv;
uniform mat4 u_mvp;
uniform float u_time, u_speed, u_flutter, u_height;
out vec2 v_uv;
out vec3 v_normal;
out vec3 v_pos;
${deformation}
void main(){
  vec3 p = cloth(a_uv);
  vec3 dx = cloth(a_uv + vec2(0.001,0.0)) - cloth(a_uv - vec2(0.001,0.0));
  vec3 dy = cloth(a_uv + vec2(0.0,0.001)) - cloth(a_uv - vec2(0.0,0.001));
  v_normal = normalize(cross(dx,dy));
  v_uv = a_uv; v_pos = p;
  gl_Position = u_mvp*vec4(p,1.0);
}`;
const fs = `#version 300 es
precision highp float;
in vec2 v_uv;
in vec3 v_normal;
in vec3 v_pos;
uniform sampler2D u_image;
uniform float u_weave;
out vec4 outColor;
void main(){
  vec3 n = normalize(v_normal);
  if(!gl_FrontFacing) n = -n;
  vec3 light = normalize(vec3(-0.5,0.75,1.2));
  float diffuse = max(dot(n,light),0.0);
  float illum = 0.58+0.48*diffuse;
  vec3 color = texture(u_image,v_uv).rgb;
  float thread = sin(v_uv.x*640.0*3.14159265)*sin(v_uv.y*400.0*3.14159265);
  float weave = 1.0 + u_weave*0.035*thread;
  float sheen = pow(max(dot(n,normalize(vec3(-0.22,0.38,1.0))),0.0),18.0)*0.025;
  color = color*illum*weave + sheen;
  // A fine stitched hem follows the edge of the printed fabric.
  float edge = min(min(v_uv.x,1.0-v_uv.x),min(v_uv.y,1.0-v_uv.y));
  float hem = 1.0-smoothstep(0.003,0.009,edge);
  color *= 1.0-hem*0.045;
  outColor = vec4(color,1.0);
}`;
ctx.state.program = ctx.utils.createProgram(vs,fs);
const bg = `#version 300 es
precision highp float;
in vec2 v_uv;
uniform vec2 u_resolution;
uniform vec2 u_span;
uniform float u_shadow;
out vec4 outColor;
void main(){
  vec2 p = (v_uv-0.5)*u_span;
  vec3 color = mix(vec3(0.88,0.90,0.91),vec3(0.97,0.97,0.955),v_uv.y);
  color -= 0.025*dot(v_uv-0.5,v_uv-0.5);
  vec2 q = abs(p-vec2(0.12,-0.17))-vec2(2.29,1.37);
  float d = length(max(q,0.0))+min(max(q.x,q.y),0.0);
  float shadow = 1.0-smoothstep(-0.24,0.38,d);
  color *= 1.0 - shadow*0.16*u_shadow;
  outColor=vec4(color,1.0);
}`;
ctx.state.background = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER,bg);
const positions=[], uvs=[], indices=[];
const nx=180, ny=112;
for(let j=0;j<=ny;j++) for(let i=0;i<=nx;i++) { positions.push(i/nx-0.5,j/ny-0.5,0); uvs.push(i/nx,j/ny); }
for(let j=0;j<ny;j++) for(let i=0;i<nx;i++) {
  const a=j*(nx+1)+i,b=a+1,c=a+nx+1,d=c+1;
  indices.push(a,b,c,b,d,c);
}
ctx.state.mesh = ctx.utils.createMesh({positions:new Float32Array(positions),uvs:new Float32Array(uvs),indices:new Uint32Array(indices)});
// Start where the fixed view used to be: slightly off-axis, far enough back that the whole flag fits.
const fov = 37, ratio0 = ctx.resolution[0] / ctx.resolution[1];
const d0 = Math.max(6.5, 3.05 / (Math.tan(fov * Math.PI / 360) * ratio0));
const r0 = Math.hypot(0.16, 0.07, d0);
ctx.state.camera = ctx.utils.createOrbitCamera({ distance: r0, theta: Math.atan2(0.16, d0), phi: Math.acos(0.07 / r0), fov, near: 0.1, far: 100, minDistance: 1.5, maxDistance: 30 });

script.render:
const gl=ctx.gl;
const ratio=ctx.resolution[0]/ctx.resolution[1];
const h=4.8/ctx.state.aspect;
const cam=ctx.state.camera;
cam.update(ctx.mouse,ctx.mousePrev,ctx.mouseDown,ctx.keys,ctx.dt);
const eye=cam.getEye(), target=cam.getTarget();
const distance=Math.hypot(eye[0]-target[0],eye[1]-target[1],eye[2]-target[2]);
const spanY=2*distance*Math.tan(cam.fov*Math.PI/360);
// The backdrop's painted shadow only lines up with the flag from the front; fade it as the view turns away.
const facing=Math.max(0,(eye[2]-target[2])/distance);
gl.disable(gl.DEPTH_TEST);
gl.disable(gl.BLEND);
ctx.utils.drawFullscreen(ctx.state.background,{u_span:[spanY*ratio,spanY],u_shadow:Math.pow(facing,8)});
gl.enable(gl.DEPTH_TEST);
gl.clear(gl.DEPTH_BUFFER_BIT);
const mvp=cam.getViewProjection(ratio);
gl.useProgram(ctx.state.program);
ctx.utils.setStandardUniforms(ctx.state.program);
ctx.utils.setUniforms(ctx.state.program,{u_mvp:mvp,u_height:h});
ctx.utils.bindTexture(ctx.state.program,'u_image',ctx.state.texture,0);
ctx.state.mesh.draw();
